# Open Pj_Learning_Lab.omv and add Pjp (Editor +).
# Select ONLY pre_score, post_score and study_hours; participant_id is optional.
# Do not select group, attendance, or columns generated by this analysis.
# Leave Browse empty, then Load this script. Both Python interpreters work.
# All observations are synthetic teaching data. Associations do not imply causation.
# True adds TWO columns through Pjp Output. Change to False and Run to REMOVE them.
# Only columns owned by this analysis are removed; original dataset columns are preserved.
WRITE_COLUMNS = True
CONFIDENCE = 0.95

import json
import math
import statistics
import uuid

mp = mzpjUseLibrary('mpmath')
sp = mzpjUseLibrary('sympy')
unc = mzpjUseLibrary('uncertainties')
jinja = mzpjUseLibrary('jinja2')
safe = mzpjUseLibrary('markupsafe')
mit = mzpjUseLibrary('more_itertools')
tabulate = mzpjUseLibrary('tabulate')

required = ['pre_score', 'post_score', 'study_hours']
generated_names = ['pj_lab_expected', 'pj_lab_loo_error']
missing = [name for name in required if name not in data]
if missing:
    raise ValueError('Select these variables in Pjp: ' + ', '.join(missing) + '.')
if any(name in data for name in generated_names):
    raise ValueError('Remove pj_lab_expected and pj_lab_loo_error from the Pjp variable selection.')
if not isinstance(WRITE_COLUMNS, bool) or not 0.80 <= CONFIDENCE <= 0.99:
    raise ValueError('WRITE_COLUMNS must be True or False; confidence must be between 0.80 and 0.99.')
row_count = len(data['post_score'])
if not row_count or any(len(data[name]) != row_count for name in required):
    raise ValueError('Select columns with the same non-zero number of rows.')
if 'participant_id' in data and len(data['participant_id']) != row_count:
    raise ValueError('The optional ID column must have the same number of rows.')

def numeric(value, name, row):
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f'Row {row+1}: {name} must be numeric or missing.')
    return float(value) if math.isfinite(value) else None

included, observations = [], []
for row in range(row_count):
    values = [numeric(data[name][row], name, row) for name in required]
    if all(value is not None for value in values):
        included.append(row)
        observations.append(values)
n, p = len(observations), 3
if n <= p+1:
    raise ValueError('At least five complete cases are required.')
means = [statistics.mean(row[j] for row in observations) for j in (0, 2)]
scales = [statistics.stdev(row[j] for row in observations) for j in (0, 2)]
if min(scales) <= 0:
    raise ValueError('Both predictors must vary.')

# QR fitting in a local high-precision context; no NumPy or SciPy is required.
# Centering and scaling improve conditioning without changing the fitted model.
with mp.workdps(40):
    X = mp.matrix([[1, (row[0]-means[0])/scales[0], (row[2]-means[1])/scales[1]]
                   for row in observations])
    y = mp.matrix([row[1] for row in observations])
    try:
        beta_scaled, _ = mp.qr_solve(X, y)
        gram_inverse = (X.T*X)**-1
    except (ValueError, ZeroDivisionError) as error:
        raise ValueError('Predictors are collinear; this model cannot be fitted.') from error
    fitted_mp = X*beta_scaled
    fitted = [float(value) for value in fitted_mp]
    residual = [float(y[i]-fitted_mp[i]) for i in range(n)]
    sse = sum(value*value for value in residual)
    average = statistics.mean(row[1] for row in observations)
    sst = sum((row[1]-average)**2 for row in observations)
    if sst <= 1e-12 or sse <= 1e-12*max(1, sst):
        raise ValueError('The outcome must vary and the model must have non-zero residual variation.')
    mse, degrees = sse/(n-p), n-p
    transform = mp.matrix([[1, -means[0]/scales[0], -means[1]/scales[1]],
                           [0, 1/scales[0], 0], [0, 0, 1/scales[1]]])
    beta_raw = transform*beta_scaled
    covariance = transform*gram_inverse*transform.T*mse
    beta = [float(value) for value in beta_raw]
    cov = [[float(covariance[i, j]) for j in range(p)] for i in range(p)]
    leverage = [float((X[i, :]*gram_inverse*X[i, :].T)[0]) for i in range(n)]
    if max(leverage) >= 1-1e-10:
        raise ValueError('Leave-one-out prediction is undefined for a case with leverage one.')

def t_p(value):
    return float(mp.betainc(mp.mpf(degrees)/2, mp.mpf('0.5'), 0,
                           mp.mpf(degrees)/(degrees+value*value), regularized=True))

low, high = 0.0, 2.0
while t_p(high) > 1-CONFIDENCE:
    high *= 2
for _ in range(65):
    middle = (low+high)/2
    if t_p(middle) > 1-CONFIDENCE:
        low = middle
    else:
        high = middle
critical = (low+high)/2
loo_error = [residual[i]/(1-leverage[i]) for i in range(n)]
loo_prediction = [observations[i][1]-loo_error[i] for i in range(n)]
rmse = math.sqrt(sse/n)
loo_rmse = math.sqrt(statistics.mean(value*value for value in loo_error))
r_squared = 1-sse/sst

# Reconstruct correlated coefficient estimates from independent latent uncertainties.
# The resulting uncertainty describes the fitted MEAN, not a new individual's score.
with mp.workdps(40):
    chol = mp.cholesky(covariance)
    latent = [unc.ufloat(0, 1) for _ in range(p)]
    uncertain_beta = [beta[i]+sum(float(chol[i, j])*latent[j] for j in range(i+1)) for i in range(p)]
at_mean = uncertain_beta[0]+uncertain_beta[1]*means[0]+uncertain_beta[2]*means[1]
if not math.isclose(at_mean.std_dev, math.sqrt(mse/n), rel_tol=1e-9, abs_tol=1e-10):
    raise ArithmeticError('The covariance-aware prediction check failed.')

terms = ['Intercept', 'pre_score', 'study_hours']
coefficients = []
for i, term in enumerate(terms):
    se = math.sqrt(cov[i][i])
    coefficients.append({'Term':term, 'Estimate':beta[i], 'SE':se, 't':beta[i]/se,
                         'df':degrees, 'p':t_p(beta[i]/se),
                         'Lower':beta[i]-critical*se, 'Upper':beta[i]+critical*se})

environment = jinja.Environment(autoescape=True)
cards = [('Complete cases', str(n), f'{row_count-n} rows excluded'),
         ('R squared', f'{r_squared:.3f}', 'In-sample explained variation'),
         ('Training RMSE', f'{rmse:.2f}', 'Fitted on the same observations'),
         ('Leave-one-out RMSE', f'{loo_rmse:.2f}', 'Each case predicted without itself')]
overview = environment.from_string('''
<section style="font:14px/1.6 sans-serif;color:#334155;max-width:980px">
<div style="color:#64748b;font-size:11px;letter-spacing:.08em">SYNTHETIC DATA · PJP PREDICTION STUDIO</div>
<h2 style="color:#3e6da9;margin:4px 0">From explanation to prediction</h2>
<p>Predict follow-up score from initial score and study hours. Compare apparent fit with
leave-one-out performance, then explore the fitted model without rerunning Python.</p>
<div style="display:flex;gap:12px;flex-wrap:wrap;margin:16px 0">{% for label,value,note in cards %}
<div style="flex:1;min-width:180px;background:#f0f5fa;border-top:3px solid #3e6da9;border-radius:8px;padding:14px">
<div style="font-size:12px;color:#64748b">{{label}}</div><div style="font-size:25px;color:#3e6da9;font-weight:600">{{value}}</div>
<div style="font-size:12px">{{note}}</div></div>{% endfor %}</div>
<p>{{output_note}}</p></section>''')
output_note = ('Two columns are returned: pj_lab_expected (full-model fitted score) and pj_lab_loo_error '
               '(observed minus leave-one-out predicted score). Excluded rows remain missing.' if WRITE_COLUMNS else
               'Column output is disabled. Previously created columns owned by this analysis are removed on Run.')
mzpjShowHtml(overview.render(cards=cards, output_note=output_note), name='prediction_overview', title='Prediction Studio')
mzpjShowTable(coefficients, name='prediction_coefficients', title='Adjusted associations · follow-up score',
              formats={'p':'pvalue'}, column_groups={'Lower':f'{CONFIDENCE:.0%} CI', 'Upper':f'{CONFIDENCE:.0%} CI'},
              notes=['Unstandardized coefficients. Both predictors enter the same model, with an intercept.',
                     'Exact t intervals assume independent normal errors with constant variance and a correct linear mean model.',
                     'No group comparison or causal effect is estimated.'])
mzpjShowTable([{'N':n, 'R squared':r_squared, 'Training RMSE':rmse, 'LOO RMSE':loo_rmse,
                'Residual SD':math.sqrt(mse), 'Mean prediction SE':at_mean.std_dev}],
              name='prediction_validation', title='Training versus leave-one-out performance',
              notes=['LOO error = residual / (1 − leverage); the model is not tuned or selected on these data.',
                     'LOO RMSE estimates prediction error, not a confidence limit or evidence of external validity.',
                     'Mean prediction SE is evaluated at the mean predictor values; it is not individual prediction error.'])

if WRITE_COLUMNS:
    for name, values in zip(generated_names, (fitted, loo_error)):
        output = [None]*row_count
        for row, value in zip(included, values):
            output[row] = float(value)
        data[name] = output

labels = data.get('participant_id', [f'Row {i+1}' for i in range(row_count)])
points = [{'before':row[0], 'after':row[1], 'hours':row[2], 'fitted':fitted[i],
           'loo':loo_prediction[i], 'label':str(labels[included[i]]), 'row':included[i]+1}
          for i, row in enumerate(observations)]
payload = json.dumps({'beta':beta, 'cov':cov, 'mse':mse, 'critical':critical,
                      'confidence':CONFIDENCE, 'points':points, 'means':means}, allow_nan=False)
for character, escaped in (('&', '\\u0026'), ('<', '\\u003c'), ('>', '\\u003e'),
                           ('\u2028', '\\u2028'), ('\u2029', '\\u2029')):
    payload = payload.replace(character, escaped)
root_id = 'prediction_'+uuid.uuid4().hex
if not d3_script:
    raise RuntimeError('The bundled D3 library is unavailable.')
html = d3_script+r'''
<style>
.mzpj-predict{font:13px/1.55 sans-serif;color:#334155;max-width:100%}
.mzpj-predict summary{color:#3e6da9;font-weight:600;cursor:pointer;padding:10px 0;border-block:1px solid #dce5f0}
.mzpj-predict .tools{display:flex;flex-wrap:wrap;gap:18px;align-items:center;padding:14px 0}
.mzpj-predict label{display:flex;align-items:center;gap:8px}
.mzpj-predict input[type=range]{width:140px;accent-color:#3e6da9}
.mzpj-predict select,.mzpj-predict button{font:inherit;border:1px solid #bfd0e5;background:white;color:#3e6da9;border-radius:5px;padding:4px 8px}
.mzpj-predict .viewport{max-width:100%;overflow:auto;max-height:560px}
.mzpj-predict .status{background:#f0f5fa;border-left:3px solid #3e6da9;padding:12px 16px;margin-top:10px;font-variant-numeric:tabular-nums}
.mzpj-predict .point{cursor:pointer}.mzpj-predict .point:focus{outline:none;stroke:#ed7953;stroke-width:3}
</style>
<details class="mzpj-predict" id="__ROOT__" open><summary>Prediction explorer · adjust a scenario and compare validation</summary>
<div class="tools">
<label>Initial score <input class="before" aria-label="Initial score" type="range" step="0.1"><output class="before-value"></output></label>
<label>Study hours <input class="hours" aria-label="Study hours" type="range" step="0.1"><output class="hours-value"></output></label>
<label>Band <select class="band"><option value="mean">Mean response CI</option><option value="individual">Individual prediction interval</option></select></label>
<label>Validation <select class="validation"><option value="loo">Leave-one-out predictions</option><option value="fitted">Full-model fitted scores</option></select></label>
<button type="button">Reset</button></div>
<div class="viewport"></div>
<div class="status" role="status" aria-live="polite"></div>
<p class="case" role="status" aria-live="polite">Hover or focus a point to inspect a student.</p>
<p>The left curve holds initial score fixed at the slider value. Its band uses coefficient covariance;
the individual interval additionally includes residual variance. Points show raw observations with varying initial scores,
so their distances from this conditional curve are not regression residuals.
The right panel evaluates complete cases; sliders do not refit the model. Predictions are not bounded to 0–100.
Stay within observed ranges and avoid unsupported combinations. Synthetic data do not establish causal effects.</p>
</details><script>
(()=>{
const root=document.getElementById('__ROOT__'),P=__PAYLOAD__,points=P.points;
const W=960,H=420,top=48,bottom=335,L=[65,550],R=[430,920];
const svg=d3.select(root.querySelector('.viewport')).append('svg').attr('width',W).attr('height',H).attr('viewBox',`0 0 ${W} ${H}`).attr('role','group').attr('aria-label','Conditional prediction and observed versus predicted score');
const fmt=d3.format('.2f'), x=d3.scaleLinear().domain(d3.extent(points,d=>d.hours)).range([L[0],R[0]]);
function domain(values){const [a,b]=d3.extent(values),pad=(b-a||1)*.08;return [a-pad,b+pad];}
const y=d3.scaleLinear().range([bottom,top]),common=domain(points.flatMap(d=>[d.after,d.loo,d.fitted]));
const vx=d3.scaleLinear().domain(common).range([L[1],R[1]]),vy=d3.scaleLinear().domain(common).range([bottom,top]);
function text(x,y,value){return svg.append('text').attr('x',x).attr('y',y).attr('text-anchor','middle').attr('fill','#334155').text(value);}
text(248,22,'Conditional response · fixed initial score');text(735,22,'Observed versus predicted');
text(248,385,'Study hours');text(735,385,'Predicted follow-up score');
text(90,40,'Follow-up');text(580,40,'Observed');
svg.append('g').attr('transform',`translate(0,${bottom})`).call(d3.axisBottom(x).ticks(5));
const ya=svg.append('g').attr('transform',`translate(${L[0]},0)`);
svg.append('g').attr('transform',`translate(0,${bottom})`).call(d3.axisBottom(vx).ticks(5));
svg.append('g').attr('transform',`translate(${L[1]},0)`).call(d3.axisLeft(vy).ticks(5));
svg.append('line').attr('x1',vx(common[0])).attr('x2',vx(common[1])).attr('y1',vy(common[0])).attr('y2',vy(common[1])).attr('stroke','#94a3b8').attr('stroke-dasharray','5 4');
const band=svg.append('path').attr('fill','#3e6da9').attr('fill-opacity',.16);
const curve=svg.append('path').attr('fill','none').attr('stroke','#3e6da9').attr('stroke-width',2);
const raw=svg.append('g').selectAll('circle').data(points).join('circle').attr('r',3.4).attr('cx',d=>x(d.hours)).attr('fill','#3e6da9').attr('fill-opacity',.38);
const validation=svg.append('g').selectAll('circle').data(points).join('circle').attr('r',4).attr('cy',d=>vy(d.after)).attr('fill','#3e6da9').attr('fill-opacity',.7);
for(const layer of [raw,validation])layer.attr('class','point').attr('tabindex',0)
 .attr('aria-label',d=>`${d.label}, initial ${fmt(d.before)}, follow-up ${fmt(d.after)}, study hours ${fmt(d.hours)}`)
 .on('pointerenter',(_,d)=>inspect(d)).on('focus',(_,d)=>inspect(d))
 .on('pointerleave',()=>inspect(null)).on('blur',()=>inspect(null));
function inspect(d){for(const layer of [raw,validation])layer.attr('stroke',v=>d&&d.row===v.row?'#ed7953':'none').attr('stroke-width',3);
 root.querySelector('.case').textContent=d?`${d.label} · dataset row ${d.row} · observed ${fmt(d.after)} · fitted ${fmt(d.fitted)} · leave-one-out prediction ${fmt(d.loo)}`:'Hover or focus a point to inspect a student.';}
const interval=svg.append('line').attr('stroke','#ed7953').attr('stroke-width',3);
const scenario=svg.append('circle').attr('r',6).attr('fill','#ed7953').attr('stroke','white').attr('stroke-width',2);
function predict(before,hours,individual){const v=[1,before,hours],mean=d3.sum(v,(a,i)=>a*P.beta[i]);
 const variance=d3.sum(v,(a,i)=>d3.sum(v,(b,j)=>a*b*P.cov[i][j]))+(individual?P.mse:0),margin=P.critical*Math.sqrt(Math.max(0,variance));
 return {hours,mean,lower:mean-margin,upper:mean+margin};}
const before=root.querySelector('.before'),hours=root.querySelector('.hours');
function configure(input,values,initial){const [lo,hi]=d3.extent(values);input.min=lo;input.max=hi;input.value=initial;}
configure(before,points.map(d=>d.before),P.means[0]);configure(hours,points.map(d=>d.hours),P.means[1]);
function update(){const a=+before.value,h=+hours.value,individual=root.querySelector('.band').value==='individual',mode=root.querySelector('.validation').value;
 root.querySelector('.before-value').textContent=fmt(a);root.querySelector('.hours-value').textContent=fmt(h);
 const [lo,hi]=x.domain(),grid=d3.range(81).map(i=>predict(a,lo+(hi-lo)*i/80,individual)),current=predict(a,h,individual);
 y.domain(domain([...points.map(d=>d.after),...grid.flatMap(d=>[d.lower,d.upper])]));
 ya.call(d3.axisLeft(y).ticks(5));
 band.attr('d',d3.area().x(d=>x(d.hours)).y0(d=>y(d.lower)).y1(d=>y(d.upper))(grid));
 curve.attr('d',d3.line().x(d=>x(d.hours)).y(d=>y(d.mean))(grid));
 raw.attr('cy',d=>y(d.after));validation.attr('cx',d=>vx(d[mode]));
 interval.attr('x1',x(h)).attr('x2',x(h)).attr('y1',y(current.lower)).attr('y2',y(current.upper));scenario.attr('cx',x(h)).attr('cy',y(current.mean));
 root.querySelector('.status').textContent=`Initial score ${fmt(a)} · ${fmt(h)} study hours → expected follow-up ${fmt(current.mean)} · ${Math.round(P.confidence*100)}% ${individual?'individual prediction interval':'mean response CI'} [${fmt(current.lower)}, ${fmt(current.upper)}]`;
}
before.addEventListener('input',update);hours.addEventListener('input',update);
for(const select of root.querySelectorAll('select'))select.addEventListener('change',update);
root.querySelector('button').addEventListener('click',()=>{before.value=P.means[0];hours.value=P.means[1];root.querySelector('.band').value='mean';root.querySelector('.validation').value='loo';inspect(null);update();});
update();
})();</script>'''
mzpjShowHtml(html.replace('__ROOT__', root_id).replace('__PAYLOAD__', payload),
             name='prediction_explorer', title='Prediction Studio · interactive scenarios')
mzpjShowHistogram({'LOO error':loo_error}, variable='LOO error', bins=18,
                  name='prediction_errors', title='Leave-one-out errors · observed minus predicted', expanded=False)

b0, b1, b2, initial, hours = sp.symbols('b0 b1 b2 initial hours')
formula = b0+b1*initial+b2*hours
gradient = [sp.diff(formula, term) for term in (b0,b1,b2)]
methods = environment.from_string('''<section style="font:13px/1.6 sans-serif;color:#334155">
<details><summary style="cursor:pointer;color:#3e6da9">Methods · symbolic model and reproducibility</summary>
<p>Model: <code>{{formula}}</code>. Coefficient gradient: <code>{{gradient}}</code>.
Uncertainty of the fitted mean is gradient × coefficient covariance × gradient transpose.
The uncertainties library independently checks this calculation at the mean predictor values.</p>
<p>mpmath fits OLS by QR after scaling predictors. t probabilities and critical values also use mpmath.
No pandas, NumPy, SciPy or matplotlib installation is needed for this example.</p>
<p>LOO prediction removes each observation in turn analytically through the hat-matrix identity.
Missing values are excluded jointly for the three model variables; missing ID labels do not exclude observations.</p>
<p>Active supplied libraries: {{libraries}}.</p></details></section>''')
mzpjShowHtml(methods.render(formula=str(formula), gradient=str(gradient),
    libraries=', '.join(row['Library']+' '+row['Version'] for row in mzpjListLibraries() if row['Active'])),
    name='prediction_methods', title='Methods')
# more-itertools takes a short label preview without changing the analysis rows.
first_labels = list(mit.take(6, (str(labels[row]) for row in included)))
print(tabulate.tabulate([[r['Term'],r['Estimate'],r['SE']] for r in coefficients],
                        headers=['Term','Estimate','SE'],floatfmt='.4f'))
print('First complete-case labels:', ', '.join(first_labels))
print(safe.escape('Observed < expected is a negative prediction error.'))
print(f'{n} complete cases; training RMSE {rmse:.3f}; leave-one-out RMSE {loo_rmse:.3f}.')
print('Two Pjp output columns requested.' if WRITE_COLUMNS else 'No output columns requested; previous outputs are cleared.')
